import{_ as e,o as r,c as a,ae as o}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"omm Development Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"guide/roadmap.md","filePath":"guide/roadmap.md"}'),i={name:"guide/roadmap.md"};function s(n,t,d,l,c,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="omm-development-roadmap" tabindex="-1">omm Development Roadmap <a class="header-anchor" href="#omm-development-roadmap" aria-label="Permalink to &quot;omm Development Roadmap&quot;">​</a></h1><blockquote><p>Current: v0.2.0 — core skeleton complete, workflow runtime pending</p></blockquote><h2 id="current-state-summary" tabindex="-1">Current State Summary <a class="header-anchor" href="#current-state-summary" aria-label="Permalink to &quot;Current State Summary&quot;">​</a></h2><p>omm covers ~15-20% of oh-my-codex&#39;s core functionality. The foundation is solid:</p><ul><li><strong>5 tools</strong> registered via OpenClaw Plugin ABI</li><li><strong>5 skills</strong> defined (2 tool-dispatch, 3 model-driven state machines)</li><li><strong>1 MCP server</strong> for out-of-process state access</li><li><strong>State validation</strong> for ralph/autopilot/team modes</li><li><strong>25 tests</strong> passing, CI pipeline operational</li><li><strong>Compliance toolchain</strong> (scan-names, verify-bundle, verify-provenance)</li></ul><p>See <a href="/guide/architecture.html">Architecture Overview</a> for module details.</p><hr><h2 id="phase-1-workflow-runtime" tabindex="-1">Phase 1: Workflow Runtime <a class="header-anchor" href="#phase-1-workflow-runtime" aria-label="Permalink to &quot;Phase 1: Workflow Runtime&quot;">​</a></h2><p><strong>Goal:</strong> Make ralph/autopilot/team workflows production-usable with persistence, mutual exclusion, and pipeline orchestration.</p><p><strong>Priority:</strong> High — blocks workflow usability</p><table tabindex="0"><thead><tr><th>Deliverable</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Workflow transition guard</td><td>Enforce single active workflow mode at a time; reject <code>active=true</code> writes when another mode is already active</td><td>Done (2026-04-26)</td></tr><tr><td>Ralph persistence</td><td>Progress ledger and PRD management; enable resume across sessions</td><td>Done (2026-04-26)</td></tr><tr><td>Pipeline stage definitions</td><td>Define autopilot stage sequence (analyze → plan → execute → verify); enable structured multi-step execution</td><td>Done (2026-04-26)</td></tr></tbody></table><p><strong>Exit criteria:</strong></p><ul><li>[x] Only one of ralph/autopilot/team can be <code>active=true</code> at any time</li><li>[x] Ralph can resume from persisted state after session restart</li><li>[x] Autopilot executes a multi-step plan with per-step verification</li><li>[x] All existing tests continue to pass + new tests for transition guard</li></ul><hr><h2 id="phase-2-extended-mcp" tabindex="-1">Phase 2: Extended MCP <a class="header-anchor" href="#phase-2-extended-mcp" aria-label="Permalink to &quot;Phase 2: Extended MCP&quot;">​</a></h2><p><strong>Goal:</strong> Add memory and trace MCP servers for richer workflow context.</p><p><strong>Priority:</strong> Medium — enhances workflow quality but not blocking</p><table tabindex="0"><thead><tr><th>Deliverable</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Memory MCP server</td><td>Persistent key-value memory store for cross-session context</td><td>Done (2026-04-26)</td></tr><tr><td>Trace MCP server</td><td>Execution trace recording and querying</td><td>Done (2026-04-26)</td></tr></tbody></table><p><strong>Exit criteria:</strong></p><ul><li>[x] Memory MCP: read/write/list/delete operations over stdio</li><li>[x] Trace MCP: record execution events, query by session/time range</li><li>[x] Both servers follow zero-dependency pattern (<a href="/reference/adrs/003.html">ADR-003</a>)</li><li>[x] Consumer integration updated (seed config, bundle manifest)</li></ul><hr><h2 id="phase-3-polish-and-extensibility" tabindex="-1">Phase 3: Polish and Extensibility <a class="header-anchor" href="#phase-3-polish-and-extensibility" aria-label="Permalink to &quot;Phase 3: Polish and Extensibility&quot;">​</a></h2><p><strong>Goal:</strong> Improve developer experience, add extensibility hooks, expand test coverage.</p><p><strong>Priority:</strong> Low — quality-of-life improvements</p><table tabindex="0"><thead><tr><th>Deliverable</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>Hook plugin system</td><td>Dynamic hook loading from <code>.omm/hooks/*.mjs</code></td><td>Done (2026-04-26)</td></tr><tr><td>Agent prompt library</td><td>Reusable role prompts (planner, architect, executor, verifier)</td><td>Done (2026-04-26)</td></tr><tr><td>Expanded test coverage</td><td>Integration tests, MCP server tests, edge case coverage</td><td>Done (2026-04-26) — 96.83% statements / 98.27% functions / 91.07% branches</td></tr></tbody></table><p><strong>Exit criteria:</strong></p><ul><li>[x] Custom hooks can be loaded and dispatched at session lifecycle points</li><li>[x] At least 5 agent prompts available for common workflow roles</li><li>[x] Test coverage ≥ 80% across all packages</li></ul><hr><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h2><p>These are deliberately excluded based on architectural decisions:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Reason</th><th>ADR</th></tr></thead><tbody><tr><td>Standalone CLI</td><td>OpenClaw Gateway provides tool dispatch</td><td><a href="/reference/adrs/001.html">ADR-001</a></td></tr><tr><td>tmux/worktree parallelism</td><td>Host provides team primitives</td><td><a href="/reference/adrs/002.html">ADR-002</a></td></tr><tr><td>HUD / status bar</td><td>Host UI layer (Electron) provides equivalent</td><td>N/A</td></tr><tr><td>Notification subsystem</td><td>Host (MatrixAssistant) has its own notifications</td><td>N/A</td></tr><tr><td>Rust native crates</td><td>Not needed for plugin-only architecture</td><td><a href="/reference/adrs/001.html">ADR-001</a></td></tr><tr><td>Code-intel MCP</td><td>OpenClaw may provide LSP integration natively</td><td>N/A</td></tr></tbody></table>',31)])])}const u=e(i,[["render",s]]);export{m as __pageData,u as default};
